#include "hydra_ygg_sink/yggdrasil_sink.h"

#include <config_utilities/config.h>
#include <config_utilities/printing.h>
#include <config_utilities/factory.h>
#include <config_utilities/validation.h>
#include <glog/logging.h>

#include <fstream>
#include <iostream>
#include <mutex>
#include <sstream>

#include "ygg_bridge_cxx/lib.h"  // generated by corrosion_add_cxxbridge

namespace hydra_ygg {

namespace {
static const auto registration =
    config::RegistrationWithConfig<hydra::BackendModule::Sink, YggdrasilSink, YggdrasilSink::Config>(
        "YggdrasilSink");
}

struct YggdrasilSink::Impl {
  mutable std::mutex mutex;
  mutable rust::Box<hydra_ygg::Mirror> mirror = new_mirror();
  mutable size_t updates = 0;
};

void declare_config(YggdrasilSink::Config& config) {
  using namespace config;
  name("YggdrasilSink::Config");
  field(config.scratch_path, "scratch_path");
  field(config.output_path, "output_path");
  field(config.compare_every, "compare_every");
  field(config.tolerance, "tolerance");
  check(config.compare_every, GE, 0, "compare_every");
}

YggdrasilSink::YggdrasilSink(const Config& config)
    : config(config::checkValid(config)), impl_(std::make_unique<Impl>()) {
  // std::cerr, not glog: Hydra's glog setup hides INFO/WARNING from the launch output.
  std::cerr << "[YggdrasilSink] created, scratch=" << config.scratch_path
            << " compare_every=" << config.compare_every << std::endl;
}

YggdrasilSink::~YggdrasilSink() {
  if (config.output_path.empty()) {
    return;
  }
  try {
    impl_->mirror->save(config.output_path);
    LOG(INFO) << "[YggdrasilSink] saved mirror to " << config.output_path;
  } catch (const std::exception& e) {
    LOG(ERROR) << "[YggdrasilSink] save failed: " << e.what();
  }
}

std::string YggdrasilSink::printInfo() const { return config::toString(config); }

void YggdrasilSink::call(uint64_t timestamp_ns,
                         const spark_dsg::DynamicSceneGraph& graph,
                         const kimera_pgmo::DeformationGraph&) const {
  std::lock_guard<std::mutex> lock(impl_->mutex);
  try {
    // Stage A goes through Hydra's own JSON writer so the mirror sees exactly what dsg.json holds.
    graph.save(config.scratch_path, false);
    std::stringstream ss;
    ss << std::ifstream(config.scratch_path).rdbuf();
    const std::string json = ss.str();

    const auto stats = impl_->mirror->apply_dsg_json(json);
    ++impl_->updates;
    std::cerr << "[YggdrasilSink] update " << impl_->updates << " nodes=" << stats.nodes << " (+"
              << stats.nodes_added << " ~" << stats.nodes_updated << " -" << stats.nodes_removed
              << ") edges(+" << stats.edges_added << " -" << stats.edges_removed << ")"
              << (stats.rebuilt ? " rebuilt" : "") << " apply=" << stats.apply_us / 1000.0
              << "ms" << std::endl;
    if (config.compare_every > 0 && impl_->updates % config.compare_every == 0) {
      const auto r = impl_->mirror->compare_with(json, config.tolerance);
      if (r.equal) {
        std::cerr << "[YggdrasilSink] update " << impl_->updates << " matches Hydra (max pos err " << r.max_position_error << ")" << std::endl;
      } else {
        std::cerr << "[YggdrasilSink] update " << impl_->updates << " differs: nodes -"
                  << r.missing_nodes << "/+" << r.extra_nodes << " edges -" << r.missing_edges
                  << "/+" << r.extra_edges << " attrs " << r.mismatches << "\n"
                  << std::string(r.summary) << std::endl;
      }
    }
  } catch (const std::exception& e) {
    std::cerr << "[YggdrasilSink] update failed: " << e.what() << std::endl;
  }
}

}  // namespace hydra_ygg
